node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
const f = Math.fround;
const v = [1, 1, -0.25];
const source = v.reduce((sum, x) => f(sum + f(x / 3)), 0);
const hoisted = f(v.reduce((sum, x) => f(sum + x), 0) / 3);
assert.notEqual(source, hoisted);
const delta = f(Math.log(2 ** -24));
const w = f(Math.exp(delta));
const ordered = f(f(1 + w) + w);
const blocked = f(1 + f(w + w));
assert.notEqual(ordered, blocked);
console.log({ source, hoisted, delta, weight: w, ordered, blocked });
NODE
